(function(){
 'use strict';
 const data=window.AF_CATALOG,core=window.AssetCatalogCore,$=id=>document.getElementById(id);
 $('preview-count').textContent=data.rows.filter(r=>r.preview).length+' 条';
 const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const initial={q:'',role:'',type:'',source:'',evidence:'',reskin:'',sort:'id',page:1,size:30,view:'catalog'};
 let state={...initial},selectedId='',toastTimer;
 const roleDoc=role=>data.documents.find(d=>d.dimension==='role'&&d.name===role);
 function readLocation(){const p=new URLSearchParams(location.hash.slice(1));state={...initial,q:p.get('q')||'',role:data.roles.includes(p.get('role'))?p.get('role'):'',type:data.types.includes(p.get('type'))?p.get('type'):'',source:['inside','outside'].includes(p.get('source'))?p.get('source'):'',evidence:['used','retained','unobserved'].includes(p.get('evidence'))?p.get('evidence'):'',reskin:['direct','prepare','verify','none'].includes(p.get('reskin'))?p.get('reskin'):'',sort:['id','name','parts'].includes(p.get('sort'))?p.get('sort'):'id',page:Math.max(1,Number(p.get('page'))||1),size:[30,50,100].includes(Number(p.get('size')))?Number(p.get('size')):30,view:['documents','evidence'].includes(p.get('view'))?p.get('view'):'catalog'};selectedId=p.get('asset')||'';}
 function writeLocation(){const p=new URLSearchParams();for(const key of ['view','role','type','source','evidence','reskin','q','sort','page','size'])if(state[key]!==initial[key]&&state[key]!=='')p.set(key,state[key]);if(selectedId)p.set('asset',selectedId);history.replaceState(null,'',location.pathname+location.search+(p.size?'#'+p.toString():''));}
 function highlight(value){const text=String(value??'');const q=state.q.trim();if(!q||q.split(/\s+/).length>1)return escape(text);const n=core.normalize(text),needle=core.normalize(q),index=n.indexOf(needle);if(index<0)return escape(text);return escape(text.slice(0,index))+'<mark>'+escape(text.slice(index,index+q.length))+'</mark>'+escape(text.slice(index+q.length));}
 function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2200);}
 async function copy(text){try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(text);toast('已复制 Studio 路径');}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.left='-9999px';document.body.append(area);area.select();let ok=false;try{ok=document.execCommand('copy');}catch{}area.remove();toast(ok?'已复制 Studio 路径':'无法自动复制，请选中路径后复制');}}
 function downloadMarkdown(doc){
  const cell=value=>String(value??'').replaceAll('|','\\|').replace(/\r?\n/g,' ').replace(/\s+/g,' ').trim();
  let text,filename;
  if(doc){const records=data.rows.filter(r=>r[doc.dimension==='role'?'role':'materialType']===doc.name);text=`# ${doc.name}\n\n2026-11-18。${records.length} 条素材。程序用途与素材类型分别记录，位置不代表正式或非正式。换皮评估更新于2026-11-19；可直接出图不等于工程可直接替换，配套默认是建议对照。\n\n`;
   const headers=['编号','名称 / 原名','程序用途','素材类型','位置','引用审计','可直接出换皮图','制图单元与理由','配套与替换方案','工程保留约束','脚本或入口','依据','备注','Studio 定位'];
   text+='| '+headers.join(' | ')+' |\n| '+headers.map(()=>'---').join(' | ')+' |\n';
   text+=records.map(r=>[r.id,r.name===r.display?r.display:`${r.display} / ${r.name}`,r.role,r.materialType,r.source==='预设库'?'Prefabs 内':'Prefabs 外',r.referenceAudit?.status??'未审计',r.reskin.decision+' · '+r.reskin.workflow+'（'+r.reskin.confidence+'）',r.reskin.subject+'；'+r.reskin.unit+'；'+r.reskin.reason,[r.reskin.companions.map(c=>c.id+' '+c.name+'（'+c.relation+'）').join('；'),...r.reskin.plan.map((p,i)=>(i+1)+'. '+p)].filter(Boolean).join('；'),r.reskin.engineering.join('；'),r.entry,r.roleBasis,[r.roleNote,r.notes!==r.roleNote?r.notes:''].filter(Boolean).join('；'),`\`${r.path}\` · \`${r.locator}\``]).map(row=>'| '+row.map(cell).join(' | ')+' |').join('\n')+'\n';filename=doc.name+'.md';
  }else{text='# 素材分类文件索引\n\n905 条素材，按 7 种程序用途、13 种素材类型拆分。两组是同一批记录的不同查看方式。\n\n'+data.documents.map(d=>`- ${d.dimension==='role'?'程序用途':'素材类型'}：${d.name}（${d.count} 条）`).join('\n')+'\n';filename='素材分类文件索引.md';}
  const objectUrl=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=objectUrl;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),10000);
 }
 function referenceCell(row){const a=row.referenceAudit;return a?`<span class="reference-badge ${escape(a.key)}">${escape(a.status)}</span>`:'<span class="reference-badge">未审计</span>';}
 function referenceDetail(row){const a=row.referenceAudit;if(!a)return "";const counts=`精确/属性 ${a.directCount} · 目录/标签 ${a.indirectCount} · 重名或解析候选 ${a.ambiguousCount}`;return `<section class="detail-section"><h3>引用审计</h3><p>${referenceCell(row)}</p><p style="margin-top:9px">${counts}</p><p style="margin-top:6px">${a.noStaticReference?"本轮未解析到外部静态引用，不能据此认定无用。":"静态命中不保证运行执行；可包含模板内、模块内或禁用脚本的引用。"}${a.nameCandidateCount?" 同名字符串或配置名称仅作候选，不据此认定已引用。":""}</p>${a.evidence.length?`<ul class="reference-lines">${a.evidence.map(e=>`<li>${escape(e.script)}${e.line?":"+e.line:""}${e.enabled===false?"（脚本已禁用）":""}<br>${escape(e.reason)}</li>`).join("")}</ul>`:""}</section>`;}
 function renderNav(){const nav=[{name:'',label:'全部素材',count:data.rows.length},...data.roles.map(name=>({name,label:name==='已确认的开发测试与展示素材'?'开发测试与展示素材':name,count:data.rows.filter(r=>r.role===name).length}))];$('role-nav').innerHTML=nav.map(r=>`<button class="role-link ${state.role===r.name?'active':''}" data-role="${escape(r.name)}" ${state.role===r.name?'aria-current="true"':''}><span class="role-dot"></span><span>${escape(r.label)}</span><span class="count">${r.count}</span></button>`).join('');}
 function renderDocs(){for(const dimension of ['role','type']){const docs=data.documents.filter(d=>d.dimension===dimension);$(dimension+'-documents').innerHTML=docs.map((d,i)=>`<article class="document-card"><span class="doc-index">${String(i+1).padStart(2,'0')} / MD</span><h4>${escape(d.name)}</h4><p>${d.count} 条素材记录</p><div class="doc-actions"><button data-browse-dimension="${dimension}" data-browse-value="${escape(d.name)}">在目录中查看 →</button><a href="docs/${encodeURIComponent(d.file)}" download="${escape(d.name)}.md">下载 Markdown ↗</a></div></article>`).join('');}}
 const reskinLabels={direct:'是 · 可直接',prepare:'否 · 先准备',verify:'待确认',none:'不适用'};
 function reskinCell(row){const a=row.reskin;return `<span class="reskin-flag ${a.decisionKey}">${reskinLabels[a.decisionKey]}</span><span class="reskin-workflow">${escape(a.workflow)}</span><button class="reskin-plan-link" data-open-id="${row.id}">查看方案</button>`;}
 function reskinDetail(row){const a=row.reskin;return `<section class="detail-section reskin-detail"><h3>换皮效果图与替换方案</h3><p>${reskinCell(row)}</p><h4>${escape(a.subject)}</h4><p><b>制图单元：</b>${escape(a.unit)}</p><p><b>判断：</b>${escape(a.reason)}</p><ol>${a.plan.map(step=>`<li>${escape(step)}</li>`).join('')}</ol>${a.companions.length?`<h4>建议配套与对照</h4><ul class="reskin-companions">${a.companions.map(c=>`<li><button data-open-id="${c.id}">${escape(c.id+' '+c.name)}</button><small>${escape(c.relation)}</small></li>`).join('')}</ul>`:''}<p class="reskin-boundary">${escape(a.companionNote)}</p><h4>工程保留约束</h4><ul>${a.engineering.map(e=>`<li>${escape(e)}</li>`).join('')}</ul><details><summary>判断依据 · ${escape(a.confidence)}</summary><ul>${a.evidence.map(e=>`<li>${escape(e)}</li>`).join('')}</ul></details><p class="reskin-boundary">可直接出图不等于工程可直接替换。配套编号默认是演示建议或对照，具体关系范围以各条说明为准。</p></section>`;}
 function render(){
  renderNav();document.querySelectorAll('.view-link').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false');});
  for(const view of ['catalog','documents','evidence'])$(view+'-view').hidden=state.view!==view;
  $('page-title').textContent=state.view==='catalog'?'局内资产档案':state.view==='documents'?'分类文档':'分类与运行证据';
  $('page-subtitle').textContent=state.view==='catalog'?'按程序用途找到素材，再沿证据回到工程。':state.view==='documents'?'拆分后的 Markdown 文档，可单独查阅与下载。':'保留证据边界，让分类有据可查。';
  $('search').value=state.q;$('type-filter').value=state.type;$('source-filter').value=state.source;$('evidence-filter').value=state.evidence;$('reskin-filter').value=state.reskin;$('sort').value=state.sort;$('page-size').value=String(state.size);
  const filtered=core.filter(data.rows,state),page=core.page(filtered,state.page,state.size);state.page=page.page;
  $('collection-title').textContent=state.role||'全部素材';$('result-count').textContent=`${filtered.length} 条记录`;
  const evidenceNames={used:'有使用证据',retained:'仅观察到保留',unobserved:'本轮未观察到'};
  const chips=[state.role,state.type,state.source?state.source==='inside'?'Prefabs 内':'Prefabs 外':'',state.evidence?evidenceNames[state.evidence]:'',state.reskin?'换皮图：'+reskinLabels[state.reskin]:'',state.q?`搜索：${state.q}`:''].filter(Boolean);
  $('active-filters').innerHTML=chips.map(c=>`<span class="filter-chip">${escape(c)}</span>`).join('');
  $('asset-rows').innerHTML=page.rows.map(r=>{const evidence=core.evidence(r);return `<tr><td><div class="asset-identity">${r.preview?`<button class="asset-thumb" data-open-id="${r.id}" aria-label="查看 ${escape(r.display)} 配图与详情"><img src="${escape(r.preview.image)}" alt="" loading="lazy" width="120" height="60">${r.preview.method!=='原貌截图'?`<span class="thumb-kind">${escape(r.preview.method)}</span>`:''}</button>`:''}<div class="asset-text"><button class="asset-name" data-open-id="${r.id}">${highlight(r.display)}</button><span class="record-id">${r.id}${r.name!==r.display?' · '+escape(r.name):''}</span></div></div></td><td><span class="role-text">${escape(r.role==='已确认的开发测试与展示素材'?'开发测试与展示素材':r.role)}</span><span class="cell-secondary">${escape(r.materialType)}</span></td><td><span class="badge ${evidence.key==='unobserved'?'neutral':evidence.key}">${evidence.label}</span><span class="cell-secondary">${evidence.secondary}</span></td><td>${referenceCell(r)}</td><td class="reskin-cell">${reskinCell(r)}</td><td><span class="source-text">${r.source==='预设库'?'Prefabs 内':'Prefabs 外'}</span></td><td class="numeric">${r.parts.toLocaleString('zh-CN')}</td><td><button class="arrow-open" data-open-id="${r.id}" aria-label="查看 ${escape(r.display)} 详情">↗</button></td></tr>`;}).join('');
  $('empty-state').hidden=filtered.length>0;document.querySelector('.asset-table').hidden=filtered.length===0;
  $('page-summary').textContent=`显示 ${page.start}–${page.end} / 共 ${page.total} 条`;$('page-label').textContent=`${page.page} / ${page.totalPages}`;$('prev-page').disabled=page.page===1;$('next-page').disabled=page.page===page.totalPages;
  $('download-category').textContent=state.role?'下载此类 Markdown ↗':'下载分类索引 ↗';writeLocation();
 }
 function previewDetail(row){const p=row.preview;return p?`<figure class="detail-preview"><a href="previews/index.html#asset=${row.id}" aria-label="打开 ${escape(row.name)} 图示审查"><img src="${escape(p.image)}" alt="${escape(row.name+' · '+p.method)}" width="788" height="392"></a><figcaption><b>${escape(p.method)}</b> · 第 ${escape(p.batch||'1')} 批<p>${escape(p.note)}</p>${(p.views??[]).map(v=>`<a href="${escape(v.image)}" target="_blank" rel="noopener">${escape(v.label)} ↗</a>`).join(' · ')}</figcaption></figure>`:'';}
 function openDetail(id){
  const row=data.rows.find(r=>r.id===id);if(!row)return;selectedId=id;$('detail-id').textContent=`${row.id} / ASSET RECORD`;
  const ev=core.evidence(row),doc=roleDoc(row.role);const position=row.position?row.position.map(v=>Math.round(v*100)/100).join(', '):'未取得';
  $('detail-body').innerHTML=`<h2 id="detail-title">${escape(row.display)}</h2><p class="original-name">原始名称：${escape(row.name)}</p><div class="detail-tags"><span class="detail-tag">${escape(row.role)}</span><span class="detail-tag">${escape(row.materialType)}</span><span class="detail-tag">${row.source==='预设库'?'Prefabs 内':'Prefabs 外'}</span></div><div class="detail-grid"><div class="detail-metric"><small>几何部件 / BasePart</small><strong>${row.parts.toLocaleString('zh-CN')}</strong></div><div class="detail-metric"><small>Mesh 对象</small><strong>${row.meshes}</strong></div><div class="detail-metric"><small>内嵌脚本</small><strong>${row.scripts}</strong></div></div><section class="detail-section"><h3>STUDIO 定位</h3><div class="detail-path">${escape(row.path)}</div><p>快照序号：${escape(row.locator)}<br>位置 X, Y, Z：${escape(position)}</p></section><section class="detail-section"><h3>使用脚本或入口</h3><p>${escape(row.entry)}</p></section><section class="detail-section"><h3>分类依据</h3><p>${escape(row.roleBasis)}</p><p style="margin-top:8px"><span class="badge ${ev.key==='unobserved'?'neutral':ev.key}">${ev.label}</span> ${ev.secondary}</p></section>${referenceDetail(row)}<section class="detail-section"><h3>待核实事项与备注</h3><p>${escape([row.roleNote,row.notes!==row.roleNote?row.notes:''].filter(Boolean).join('；')||'暂无额外备注')}</p></section><div class="detail-actions"><button id="copy-path" class="button outline">复制 Studio 路径</button><a class="button outline" href="docs/${encodeURIComponent(doc.file)}" download="${escape(doc.name)}.md">下载所属分类 MD ↗</a></div>`;
  if(row.preview)$('detail-body').querySelector('.detail-grid').insertAdjacentHTML('beforebegin',previewDetail(row));
  $('detail-body').querySelector('.detail-grid').insertAdjacentHTML('afterend',reskinDetail(row));
  $('copy-path').addEventListener('click',()=>copy(row.path));if(!$('asset-dialog').open)$('asset-dialog').showModal();writeLocation();
 }
 function closeDetail(){selectedId='';$('asset-dialog').close();writeLocation();}
 function setFilter(key,value){state[key]=value;state.page=1;render();}
 function reset(){state={...initial};selectedId='';render();}
 for(const type of data.types){const o=document.createElement('option');o.value=type;o.textContent=type;$('type-filter').append(o);}
 $('search').addEventListener('input',e=>setFilter('q',e.target.value));
 for(const [id,key]of [['type-filter','type'],['source-filter','source'],['evidence-filter','evidence'],['reskin-filter','reskin'],['sort','sort']])$(id).addEventListener('change',e=>setFilter(key,e.target.value));
 $('page-size').addEventListener('change',e=>setFilter('size',Number(e.target.value)));$('reset').addEventListener('click',reset);$('empty-reset').addEventListener('click',reset);
 $('prev-page').addEventListener('click',()=>{state.page--;render();});$('next-page').addEventListener('click',()=>{state.page++;render();});
 $('close-detail').addEventListener('click',closeDetail);$('asset-dialog').addEventListener('cancel',e=>{e.preventDefault();closeDetail();});$('asset-dialog').addEventListener('click',e=>{if(e.target===$('asset-dialog')){const rect=$('asset-dialog').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDetail();}});
 document.addEventListener('click',e=>{const link=e.target.closest('a[download]');if(link&&link.getAttribute('href')?.startsWith('docs/')){e.preventDefault();const file=decodeURIComponent(link.getAttribute('href').slice(5));downloadMarkdown(data.documents.find(d=>d.file===file)||null);return;}const open=e.target.closest('[data-open-id]');if(open){openDetail(open.dataset.openId);return;}const role=e.target.closest('[data-role]');if(role){state.role=role.dataset.role;state.page=1;state.view='catalog';render();return;}const view=e.target.closest('[data-view]');if(view){state.view=view.dataset.view;render();return;}const browse=e.target.closest('[data-browse-dimension]');if(browse){state={...initial,view:'catalog'};state[browse.dataset.browseDimension]=browse.dataset.browseValue;render();return;}if(e.target.closest('.brand')){e.preventDefault();reset();}});
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!$('asset-dialog').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();state.view='catalog';render();$('search').focus();}});
 $('download-category').addEventListener('click',()=>downloadMarkdown(state.role?roleDoc(state.role):null));
 window.addEventListener('hashchange',()=>{if($('asset-dialog').open)$('asset-dialog').close();readLocation();render();if(selectedId)openDetail(selectedId);});
 for(const [key,label]of Object.entries(reskinLabels)){const o=document.createElement('option');o.value=key;o.textContent=label+' · '+data.reskinSummary.counts[key];$('reskin-filter').append(o);}
 $('reskin-counts').textContent=`可直接 ${data.reskinSummary.counts.direct} · 先准备 ${data.reskinSummary.counts.prepare} · 待确认 ${data.reskinSummary.counts.verify} · 不适用 ${data.reskinSummary.counts.none}`;
 readLocation();renderDocs();render();if(selectedId)openDetail(selectedId);
})();
